  body.replaceText("{{partner_name}}",form_partner_name);
  Logger.log(JSON.stringify(e));
  addLog(e);

  doc.saveAndClose();

  var pdfBlob = doc.getAs('application/pdf');
  
  templateResponseFolder.createFile(pdfBlob);

  GmailApp.sendEmail('dwaycik@pcs-scp.ca', 'WPL Daily Engagement Summary |'+' '+form_writer_name+' '+form_submit_date, 'Please see the attached file.'+"Logger:"+Logger.log(e), {
     attachments: [pdfBlob]});

     var byeBye = DriveApp.getFileById(copy.getId());
  byeBye.setTrashed(true); 
}

function addLog(data){
  const ss=SpreadsheetApp.getActiveSpreadsheet().getSheetByName('log');
  ss.appendRow([JSON.stringify(data)]);
}

The script doesn't fail but it keeps outputting the value which would be in column CJ in the spreadsheet is 'undefined' when it's a simple text entry.

I've been using this for over a year and there have been no issues like this. I simply added this line the other day and it's just pretending the value doesn't exist... but when I look at the value in column CJ or 87 it is clearly there a short plain text entry..

