function autoFillGoogleDocFromForm(e) {
  //e.values is an array of form values
  var timestamp = e.values[0];
  var name = e.values[1];
  var campus = e.values[2]; 
  var title = e.values[3];
  var story = e.values[4];
  var images = e.values[5];

  
  //file is the template file, and you get it by ID
  var file = DriveApp.getFileById('1nS8FmptaQod8uB_zDEVlSbpJr_nBsFhGhN3RWmaZgGQ'); 
  
  //We can make a copy of the template, name it, and optionally tell it what folder to live in
  //file.makeCopy will return a Google Drive file object
  var folder = DriveApp.getFolderById('1U-dGRwX1NnfXd9VFYzst84Kz26e-5blt')
  var parentFolder=DriveApp.getFolderById('1U-dGRwX1NnfXd9VFYzst84Kz26e-5blt');
  var newFolder=parentFolder.createFolder(campus + ' - ' + title)
  var copy = file.makeCopy(campus + ' - ' + title, newFolder); 
  
  //Once we've got the new file created, we need to open it as a document by using its ID
  var doc = DocumentApp.openById(copy.getId()); 
  
  //Since everything we need to change is in the body, we need to get that
  var body = doc.getBody(); 
  
  //Then we call all of our replaceText methods
  body.replaceText('{{name}}', name); 
  body.replaceText('{{title}}', title);  
  body.replaceText('{{story}}', story); 
  body.replaceText('{{images}}', images); 
  body.replaceText('{{campus}}', campus); 
  
  //Lastly we save and close the document to persist our changes
  doc.saveAndClose(); 
}

