I always knew how to do this with office and wanted to see if I could figure it out on Google Docs. Your code was the base I needed to make it happen. I did modify it greatly to meet my specific needs but your code was the starting point. Is there any reason why you didn't use a forEach to go through all those body.replaceText and simplify the code?
Here's what I've come up with in case it helps anyone:

function onOpen() {  //********** Add menu item ************/
  //***** Source: https://jeffreyeverhart.com/2020/09/29/auto-fill-a-google-doc-template-from-google-sheet-data/ *****/
  //********************************************************/
  const ui = SpreadsheetApp.getUi();
  const menu = ui.createMenu('AutoFill Docs');
  menu.addItem('Create New Docs', 'createNewGoogleDocs');
  menu.addToUi();
}
function findValueByKeyword(keywordToSearch,spreadsheetID,controlPanelName) { /***** Find your Data ******/
  // ***** You need to send your keyword, spreadsheet ID andd spreadsheet name to this function. *********/
  // ***** Source: Mine **********/
  // *****************************/
  // Browser.msgBox("Keyword to Search: "+keywordToSearch);
  // Browser.msgBox("Spreadsheet ID: "+spreadsheetID);
  // Browser.msgBox("Control Panel Name: "+controlPanelName);

  // Open the specified Google Sheets document
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(controlPanelName);

  // Get the data range of the sheet
  const dataRange = sheet.getDataRange();
  
  // Get all the values in the sheet as a 2D array
  const values = dataRange.getValues();
  
  // Initialize variables to store the row and column of the found keyword
  let foundRow = -1;
  let foundColumn = -1;
  
  // Loop through the values array to find the keyword
  for (let row = 0; row &lt; values.length; row++) {
    for (let col = 0; col &lt; values[row].length; col++) {
      if (values[row][col] === keywordToSearch) {
        foundRow = row;
        foundColumn = col;
        break;
      }
    }
    if (foundRow !== -1) {
      break;
    }
  }
  
  // Check if the keyword was found
  if (foundRow !== -1 &amp;&amp; foundColumn !== -1 &amp;&amp; foundColumn + 1 &lt; values[foundRow].length) {
    // Get the value in the cell in the next column
    const nextColumnValue = values[foundRow][foundColumn + 1];
    //Logger.log(&#039;Found value:&#039;, nextColumnValue);
    
    // You can return the value or use it as needed
    return nextColumnValue;
  } else {
    Logger.log(&#039;Keyword not found.&#039;);
    return null; // Keyword not found
  }
}
function createNewGoogleDocs() { //***** Combine GSheets with GDocs Template *****/
  //********************************************************/
  //********** Find and Set your values ********************/
  //********************************************************/
  // ***** Source: Heavily modified version of https://jeffreyeverhart.com/2020/09/29/auto-fill-a-google-doc-template-from-google-sheet-data/
  // ***** Note 1: Original code has option to save link in excel to the document that is created and a code to make dates friendly.
  // ***** Note 2: For some reason using {{101}} didn&#039;t work but when i removed the {{}} it all started working.
  // ******************************************************//
  const spreadsheetID = SpreadsheetApp.getActiveSpreadsheet().getId();
  const controlPanelName = &quot;Control Panel&quot;;
  const keyRow = findValueByKeyword(&quot;Key Column&quot;,spreadsheetID,controlPanelName);
  const engTxt = findValueByKeyword(&quot;ENG Text Column&quot;,spreadsheetID,controlPanelName);
  const espTxt = findValueByKeyword(&quot;ESP Text Column&quot;,spreadsheetID,controlPanelName);
  const supCol = findValueByKeyword(&quot;Support Column&quot;,spreadsheetID,controlPanelName);
  const datasheetName = findValueByKeyword(&quot;datasheetName&quot;,spreadsheetID,controlPanelName);
  const googleDocTemplateID1 = findValueByKeyword(&quot;googleDocTemplateID1&quot;,spreadsheetID,controlPanelName);
  const googleDocTemplateID2 = findValueByKeyword(&quot;googleDocTemplateID2&quot;,spreadsheetID,controlPanelName);
  let switch_templates = 0;// Set &amp; Declare Switch: check to see if both templates are used or not
  if (googleDocTemplateID2 === null || googleDocTemplateID2 === &quot;&quot;) {switch_templates = 0;} 
  else {switch_templates = 1;}// 0= off, 1=on
  const destinationFolderID = findValueByKeyword(&quot;destinationFolderID&quot;,spreadsheetID,controlPanelName);
  const languageOutput = findValueByKeyword(&quot;languageOutput&quot;,spreadsheetID,controlPanelName);
  const filenameOutput = findValueByKeyword(&quot;filenameOutput&quot;,spreadsheetID,controlPanelName)
//    Browser.msgBox(&quot;Data Sheet Name: &quot;+datasheetName);
//    Browser.msgBox(&quot;Google Doc Template ID: &quot;+googleDocTemplateID);
//    Browser.msgBox(&quot;Destination Folder: &quot;+destinationFolderID);

  const datasheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(datasheetName);

  //*******************************************************//
  //********** Connect to your files and folders **********//
  //*******************************************************//
  const destinationFolder = DriveApp.getFolderById(destinationFolderID);
  const googleDocTemplate1 = DriveApp.getFileById(googleDocTemplateID1);
  let googleDocTemplate2 = null;
  if (switch_templates === 1) {googleDocTemplate2 = DriveApp.getFileById(googleDocTemplateID2);}// if switch is on, set template 2

  //***********************************************************//
  //********** Copy template to destination folder ***********//
  //**********************************************************//
  const copy1 = googleDocTemplate1.makeCopy(filenameOutput, destinationFolder);
  let copy2 = null;
  if (switch_templates === 1) {copy2 = googleDocTemplate2.makeCopy(filenameOutput, destinationFolder);}// if switch is on, set template 2
  const doc1 = DocumentApp.openById(copy1.getId());// Once we have the copy, we then open it usin the DocumentApp
  let doc2 = null;
  if (switch_templates === 1) {doc2 = DocumentApp.openById(copy2.getId());}// if switch is on, set template 2
  let body1 = null;
  body1 = doc1.getBody();// All of the content lives in the body, so we get that for editing
  let body2 = null;
  if (switch_templates === 1) {body2 = doc2.getBody();} // if switch is on, set template 2

  //************************************//
  //********** Get your DATA **********//
  //***********************************//
  const rows = datasheet.getDataRange().getValues();
      //Browser.msgBox(&quot;Row Data: &quot;+rows);

  //***************************************//
  //********** Process your data **********//
  //***************************************//
  rows.forEach(function(row, index){
    if (index === 0) return;                  // Here we check if this row is the headers, if so we skip it. If you are NOT using headers, remove this code.
    const key = row[keyRow];                  // Get your key and make sure to set the column number correctly in the Control Panel
    if (key === null || key === &quot;&quot;) return;   // If key is null, ignore the data
    let switch_support = 0;                   // Switch to see if there is data in the support column
    if (row[supCol] === null || row[supCol]===&quot;&quot;){switch_support=0;} // Here we check to see if there is data in the support column
    else {switch_support=1;}                  // 0 = Off, 1 = On
    let newText;                              // We&#039;ll store the text based on language selection in this variable
    if (languageOutput === &#039;English&#039;) {newText = row[engTxt];}// Make sure to set this value correctly in the Control Panel
    else if (languageOutput === &#039;Spanish&#039;) {newText = row[espTxt];} // Make sure to set this value correctly in the Control Panel
    body1.replaceText(key, newText);          // Replace key codes with real text from datasheet
    if (switch_templates === 1) {body2.replaceText(key, newText);} //if switch is on, set template 2
    if (switch_support===1){                  // If there is support data, lets make it a link
      const tmpBody = body1.findText(newText);
      const tmpTxt = tmpBody.getElement().asText();
      tmpTxt.setLinkUrl(tmpBody.getStartOffset(), tmpBody.getEndOffsetInclusive(), row[supCol]);
      tmpTxt.setUnderline(false);
      tmpTxt.setForegroundColor(null);
      if (switch_templates === 1) {
        const tmpBody = body2.findText(newText);
        const tmpTxt = tmpBody.getElement().asText();
        tmpTxt.setLinkUrl(tmpBody.getStartOffset(), tmpBody.getEndOffsetInclusive(), row[supCol]);
        tmpTxt.setUnderline(false);
        tmpTxt.setForegroundColor(null);
      }        
    }
  }
  )
  //We make our changes permanent by saving and closing the document
  doc1.saveAndClose();
  if (switch_templates === 1) {doc2.saveAndClose();} //if switch is on, set template 2
}

